<?phpnamespace App\Http\Controllers\Auth;use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Facades\Auth;class StoreLoginController extends Controller{    //    public function __construct()    {        $this->middleware('guest:store')->except('logout');    }    public function showLoginForm()    {        return view('store.store_login');    }    public function login(Request $request)    {        $this->validate($request, [            'email' => 'required|exists:products,email',            'password' => 'required|string'            ]        );        $credentials = ['email' => $request->get('email'), 'password' => $request->get('password')];        if (Auth::guard('store')->attempt($credentials, true)) {            switch (Auth::guard('store')->user()->status) {                case 1:                    return redirect()->route('store.profile');                    break;                case 0:                    return redirect()->route('store.activation');                    break;                case "":                    //Design a page for blocked stores!                    break;            }        }        return redirect()->back()->withInput($request->only('email', 'remember'));    }    public function logout()    {        Auth::guard('store')->logout();//        $request->session()->invalidate();        return redirect()->route('store.login');    }}